local function decode_bundle()
    local raw = table.concat(ENCODED)
    local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for i = 1, #b64chars do lookup[string.byte(b64chars, i)] = i - 1 end
    local padded = raw
    if #padded % 4 ~= 0 then padded = padded .. string.rep("=", 4 - (#padded % 4)) end
    local output = ""
    for i = 1, #padded, 4 do
        local a = lookup[string.byte(padded, i)] or 0
        local b = lookup[string.byte(padded, i+1)] or 0
        local c = lookup[string.byte(padded, i+2)] or 0
        local d = lookup[string.byte(padded, i+3)] or 0
        local n = a * 262144 + b * 4096 + c * 64 + d
        output = output .. string.char(bit32.rshift(n, 16) % 256, bit32.rshift(n, 8) % 256, n % 256)
    end
    output = output:sub(1, 5642346)
    local key_bytes = DECODE_KEY
    local result = {}
    for i = 1, #output do
        local k = string.byte(key_bytes, ((i-1) % #key_bytes) + 1)
        result[i] = string.char(bit32.bxor(string.byte(output, i), k))
    end
    return table.concat(result)
end

local success, result = pcall(decode_bundle)
if not success or type(result) ~= "string" or #result ~= EXPECTED_LENGTH then
    warn("[ENRIQUE] Runtime bundle integrity check failed.")
    return
end

local hash = 0
for i = 1, #result do hash = (hash * 31 + string.byte(result, i)) % 2147483647 end
if hash ~= EXPECTED_HASH then
    warn("[ENRIQUE] Runtime bundle checksum mismatch.")
    return
end

local compiler = (loadstring or load)(result, "=ENRIQUE_PAID")
if not compiler then warn("[ENRIQUE] Unable to initialize protected runtime.") return end
local ok, err = pcall(compiler)
if not ok then warn("[ENRIQUE] " .. tostring(err)) end
